  tool('update_case_contact', 'tasks:write', 'Mark a contact BOUNCED, WRONG_PERSON, REPLIED (or other status) with a note, e.g. "said to email music@...". Stops follow-ups to them.', z.object({ labelId: id, contactId: id, status: z.enum(['NOT_CONTACTED', 'CONTACTED', 'REPLIED', 'BOUNCED', 'WRONG_PERSON', 'DO_NOT_CONTACT']).optional(), notes: z.string().max(1000).optional() }).strict(), async a => { scoped(a.labelId); return outreach.updateContact(db, a.labelId, caller.userId, a.contactId, a, agent) })
