  tool('mark_followup_sent', 'tasks:write', 'Record that you sent approved follow-up number n (reply in the same thread, from the user\'s email, exact approved text).', z.object({ labelId: id, draftId: id, n: z.number().int().min(1).max(4) }).strict(), async a => { scoped(a.labelId); return outreach.markFollowupSent(db, a.labelId, caller.userId, a.draftId, a.n, agent) })
  tool('record_reply', 'tasks:write', 'Someone replied to an email you sent. Summarize it in plain words. Stops all follow-ups to them and puts the case back to work.', z.object({ labelId: id, draftId: id, summary: z.string().min(1).max(2000) }).strict(), async a => { scoped(a.labelId); return outreach.recordReply(db, a.labelId, caller.userId, a.draftId, a.summary, agent) })
  tool('list_approved_drafts', 'tasks:read', 'Drafts the owner approved that are ready for you to send from the user\'s own email (Gmail/Outlook connector). After sending, call mark_draft_sent.', z.object({ labelId: id }).strict(), async a => { scoped(a.labelId); return { drafts: (await db.prepare("SELECT d.id,d.case_id AS caseId,d.kind,d.recipient,d.recipient_email AS recipientEmail,d.subject,d.body,d.approved_at,json_array_length(d.sequence_json) AS approvedFollowUps,d.attachments_json AS attachments FROM lw_case_drafts d WHERE d.label_id=? AND d.status='APPROVED' ORDER BY d.approved_at LIMIT 50").bind(a.labelId).all()).results } }, { readOnly: true })
