  tool('confirm_artist_link', 'releases:write', 'Only after the owner answered "is this you?": CONFIRMED or NOT_ME, with their words in ownerSaid.', z.object({ labelId: id, linkId: id, decision: z.enum(['CONFIRMED', 'NOT_ME']), ownerSaid: z.string().min(1).max(300) }).strict(), async a => { scoped(a.labelId); const r = await know.decideLink(db, a.labelId, caller.userId, a.linkId, a.decision); await db.prepare('INSERT INTO lw_audit_events(id,label_id,actor_id,action,payload_json) VALUES (?,?,?,?,?)').bind(crypto.randomUUID(), a.labelId, caller.userId, 'artist.link.decided_in_chat', JSON.stringify({ linkId: a.linkId, decision: a.decision, ownerSaid: a.ownerSaid, agent })).run(); return r })
  tool('sx_account', 'releases:read', 'SoundExchange account status (UNKNOWN / NOT_REGISTERED / LOCKED_OUT / ACTIVE), roles (Featured Artist, Rights Owner/SRCO) and a checklist of what to fix first. No passwords or tax data are ever stored.', z.object({ labelId: id }).strict(), async a => { scoped(a.labelId); return sx.getSxAccount(db, a.labelId, caller.userId) }, { readOnly: true })
