  tool('sx_queue', 'releases:read', 'Recordings to submit/claim at SoundExchange ("X of Y claimed"), each READY / NEEDS_INFO / BLOCKED with what is missing.', z.object({ labelId: id }).strict(), async a => { scoped(a.labelId); return sx.sxQueue(db, a.labelId, caller.userId) }, { readOnly: true })
