  tool('save_sx_recording', 'releases:write', 'Save recording facts the owner confirmed: isrc, upc, albumTitle, recordLabel, featuredArtists, masterOwner {entityName, basis COPYRIGHT_OWNER|AUTHORIZED_DESIGNEE, percent, rightsBegin INCEPTION|date, rightsEnd PERPETUITY|date}.', z.object({ labelId: id, trackId: id, work: z.object({ isrc: z.string().max(20).optional(), upc: z.string().max(20).optional(), albumTitle: z.string().max(200).optional(), recordLabel: z.string().max(100).optional(), recordingTitle: z.string().max(200).optional(), featuredArtists: z.array(z.string().max(200)).max(20).optional(), masterOwner: z.object({ entityName: z.string().max(120), basis: z.enum(['COPYRIGHT_OWNER', 'AUTHORIZED_DESIGNEE']).optional(), percent: z.number().gt(0).max(100).optional(), rightsBegin: z.string().max(10).optional(), rightsEnd: z.string().max(10).optional() }).strict().optional() }).strict() }).strict(), async a => { scoped(a.labelId); return sx.saveSxWork(db, a.labelId, caller.userId, a.trackId, a.work) })
